// Golden answer per tour line: {check lamps, P7:P4, the last 8 bytes (byte 0
// in bits 7:0)}, the ./emu line's -r and -o values (lane_model.py).
module lx_tour_exp (
    input  wire [3:0] a,
    output reg  [68:0] q
);
    always @(*) begin
        case (a)
            4'd0: q = 69'h117b3c00fa11000056;  // 56000011fa003c7b; -o 0x10
            4'd1: q = 69'h13ff6702ee31020056;  // 56000231ee0267ff; -o 0x30
            4'd2: q = 69'h11113c008214000056;  // 5600001482003c11; -o 0x10
            4'd3: q = 69'h124322000017010056;  // 5600011700002243; -o 0x20
            4'd4: q = 69'h10cab0000007050056;  // 560005070000b0ca; -o 0x00
            4'd5: q = 69'h161cea000011030056;  // 560003110000ea1c; -o 0x60
            4'd6: q = 69'h164dc7000011040056;  // 560004110000c74d; -o 0x60
            4'd7: q = 69'h124322000017010056;  // 5600011700002243; -o 0x20
            4'd8: q = 69'h124322000017010056;  // 5600011700002243; -o 0x20
            4'd9: q = 69'h18120f000017060056;  // 5600061700000f12; -o 0x80
            4'd10: q = 69'h11f241efcbcec30041;  // 4100c3cecbef41f2; -o 0x10
            4'd11: q = 69'h19a356de0ae90449;  // 4904e90ade56a319; -o unchecked
            default: q = 69'h0;
        endcase
    end
endmodule

// Number of tour lines
module lx_tour_n (output wire [3:0] n);
    assign n = 4'd12;
endmodule

// Words, 6 characters, HEX5 (left) in bits 29:25 ... HEX0 in bits 4:0.
// 0-6 the decision of a 'V' record (its status); 8-15 the tag presets (SW5:3);
// 16-22 the board's own words (digits are filled in by the fabric).
module lx_text (
    input  wire [4:0] a,
    output reg  [29:0] q
);
    always @(*) begin
        case (a)
            5'd0: q = 30'h19155e0e;  // "CHArGE"
            5'd1: q = 30'h295fe150;  // "no tAG"
            5'd2: q = 30'h193514bf;  // "CLASS "
            5'd3: q = 30'hb804dd4;  // "StOLEn"
