            5'd5: q = 30'h3efbb9df;  // " FrEE "
            5'd6: q = 30'h193015cd;  // "CLOSEd"
            5'd7: q = 30'h3fffffff;  // "      "
            5'd8: q = 30'h3f4ad1df;  // " nonE "
            5'd9: q = 30'h3ec55fff;  // " CAr  "
            5'd10: q = 30'h275bdf5f;  // "LorrY "
            5'd11: q = 30'h3ec52fff;  // " CAb  "
            5'd12: q = 30'hb804dd4;  // "StOLEn"
            5'd13: q = 30'h193051df;  // "CLOnE "
            5'd14: q = 30'h3eb537ff;  // " bAd  "
            5'd15: q = 30'h3ef55fff;  // " FAr  "
            5'd16: q = 30'h1d7bffff;  // "Err   "
            5'd17: q = 30'h24dfffff;  // "Id    "
            5'd18: q = 30'h295fc9bf;  // "no Id "
